        ('882bb5e70283711a0c90460b64b632f83786eaf265e1e044bfbe288e6144ae98', 'timeframe', 'gold_unified_event_star', '1.6.0', '{"data":{"categories":{"invoice_lines":{"field":{"logicalType":"date","mappingRole":"time","physicalType":"TIMESTAMP","required":true},"time_column":"invoiced_at","time_grain":"minute"}},"fields":{"grain":{"logicalType":"string","physicalType":"VARCHAR","required":true},"period_start":{"logicalType":"date","physicalType":"TIMESTAMP","required":true}}},"expert_context":{"categories":{"invoice_lines":{"time_column_meaning":"Invoice timestamp; the declared time column.","vintage":""}},"cross_category_joins":[{"calendar_grain":"hour","conformed_keys":["airport_iata"],"example_sql":"SELECT flights.carrier_code, avg(flights.dep_delay_minutes) AS avg_dep_delay_minutes FROM gold.mart_flights_typed AS flights JOIN gold.mart_airport_weather_typed AS airport_weather ON flights.origin_airport = airport_weather.airport_code AND flights.departure_hour_utc = airport_weather.observed_hour_utc WHERE airport_weather.precip_inches > 0 GROUP BY flights.carrier_code ORDER BY avg_dep_delay_minutes DESC","floor":0.99,"join_condition":"flights.origin_airport = airport_weather.airport_code AND flights.departure_hour_utc = airport_weather.observed_hour_utc","left":"flights","measured_completeness":0.9994,"name":"flights_to_origin_weather","note":"Every flight''s weather at its origin airport in its departure hour, both sides on the conformed calendar (UTC hours) and the conformed airport code. Measured 0.9994 over the typed surfaces at the Arc 6 build: 97 of 166,158 flights fall in the six airport-hours the nycflights13 weather feed has no observation for. The floor is declared below the measurement so a weather refresh that adds coverage passes and one that loses it fails (the M2 discipline, D-41). Destination weather is out of reach by construction: the weather feed covers the three New York City airports only.","right":"airport_weather"}],"fields":{"grain":{"meani